action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger");
  const html = await r.text();
  console.log(html.replace(/\s+/g," ").slice(0,1500));
})();
'

